const auth = await tools.vercel_api.user.personalvercelapi.user.getAuthUser({});
const teams = await tools.vercel_api.user.personalvercelapi.teams.getTeams({ limit: 100 });
if (!auth.ok) return { authError: auth.error };
if (!teams.ok) return { teamsError: teams.error };
const user = auth.data.user;
return {
  user: {
    id: user.id,
    uid: user.uid,
    email: user.email,
    username: user.username,
    name: user.name
  },
  teams: teams.data.teams.map((team) => ({
    id: team.id,
    slug: team.slug,
    name: team.name,
    membership: team.membership ? {
      role: team.membership.role,
      confirmed: team.membership.confirmed
    } : undefined
  }))
};

