        platform: PhotonWebhookPlatform.make("local_imessage"),
      },
    });
    const cases = [
      {
        body: spacePlatform,
        checkpoint: "spacePlatform",
        classification: "unknown",
      },
      {
        body: messagePlatform,
        checkpoint: "messagePlatform",
        classification: "unknown",
      },
      {
        body: senderPlatform,
